const summariesByIDs = `-- name: SummariesByIDs :many
SELECT id, number, party_id, order_date, due_date, grand_total, status,
       branch_id, tax_invoice_number, tax_invoice_date
FROM sales_orders
WHERE id IN (/*SLICE:ids*/?)
`

type SummariesByIDsRow struct {
	ID               int64
	Number           string
	PartyID          int64
	OrderDate        time.Time
	DueDate          sql.NullTime
	GrandTotal       int64
	Status           string
	BranchID         int64
	TaxInvoiceNumber sql.NullString
	TaxInvoiceDate   sql.NullTime
}

func (q *Queries) SummariesByIDs(ctx context.Context, ids []int64) ([]SummariesByIDsRow, error) {
	query := summariesByIDs
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummariesByIDsRow{}
	for rows.Next() {
		var i SummariesByIDsRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.PartyID,
			&i.OrderDate,
			&i.DueDate,
			&i.GrandTotal,
			&i.Status,
			&i.BranchID,
			&i.TaxInvoiceNumber,
			&i.TaxInvoiceDate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const switchToNet = `-- name: SwitchToNet :execresult
UPDATE sales_orders
SET payment_terms = 'net', due_date = ?,
    credit_approved_by = ?, credit_approved_at = ?,
    updated_at = ?, updated_by = ?
WHERE id = ? AND status = 'confirmed' AND payment_terms IN ('cod', 'prepaid')
`

type SwitchToNetParams struct {
	DueDate    sql.NullTime
	ActorID    sql.NullInt64
	ApprovedAt sql.NullTime
	Now        time.Time
	ID         int64
}

// CAS: only a confirmed cash-terms order (cod or prepaid) may switch.
// The approval (who/when, SL-09) is stamped in the same statement: the credit
// switch is the approval, whichever path reaches it (approve-credit endpoint or
// the delivery settlement switch_to_net).
func (q *Queries) SwitchToNet(ctx context.Context, arg SwitchToNetParams) (sql.Result, error) {
	return q.db.ExecContext(ctx, switchToNet,
		arg.DueDate,
		arg.ActorID,
		arg.ApprovedAt,
		arg.Now,
		arg.ActorID,
		arg.ID,
	)
}

const transitionOrder = `-- name: TransitionOrder :execresult
UPDATE sales_orders
SET status = ?, updated_at = ?, updated_by = ?,
    completed_at = CASE WHEN ? = 'completed' THEN ? ELSE completed_at END
WHERE id = ? AND status IN (/*SLICE:from_statuses*/?)
`

type TransitionOrderParams struct {
	ToStatus     string
	Now          time.Time
	ActorID      sql.NullInt64
	Stamp        sql.NullTime
	ID           int64
	FromStatuses []string
}

// CAS: moves the status only from one of the allowed origins.
func (q *Queries) TransitionOrder(ctx context.Context, arg TransitionOrderParams) (sql.Result, error) {
	query := transitionOrder
	var queryParams []interface{}
	queryParams = append(queryParams, arg.ToStatus)
	queryParams = append(queryParams, arg.Now)
	queryParams = append(queryParams, arg.ActorID)
	queryParams = append(queryParams, arg.ToStatus)
	queryParams = append(queryParams, arg.Stamp)
	queryParams = append(queryParams, arg.ID)
	if len(arg.FromStatuses) > 0 {
		for _, v := range arg.FromStatuses {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", strings.Repeat(",?", len(arg.FromStatuses))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", "NULL", 1)
	}
	return q.db.ExecContext(ctx, query, queryParams...)
}

